SELECT t_storage.*, t_storage_list.*, t_wh.warehouse_name FROM idevelop_device_storage t_storage LEFT JOIN idevelop_device_storage_list t_storage_list ON t_storage.id = t_storage_list.storage_id AND t_storage_list.is_deleted = 0 left join idevelop_warehouse t_wh on t_storage.warehouse = t_wh.uuid and t_wh.is_deleted = 0 WHERE t_storage.is_deleted = 0 AND t_storage.id IN (
#{id}
) ORDER BY t_storage.create_time DESC

SELECT
t_storage.*,
t_storage_list.*,
t_wh.warehouse_name
FROM
idevelop_device_storage t_storage
LEFT JOIN idevelop_device_storage_list t_storage_list ON t_storage.id = t_storage_list.storage_id AND
t_storage_list.is_deleted = 0
left join idevelop_warehouse t_wh on t_storage.warehouse = t_wh.uuid and t_wh.is_deleted = 0
WHERE
t_storage.is_deleted = 0
AND t_storage.region_code = #{regionCode}
and t_storage.serial_number = #{serialNumber}
and DATE_FORMAT(t_storage.storage_time,'%Y-%m-%d') =
    #{storageDate}

and t_storage.`status` = #{status}
and t_storage.wbs_project = #{wbsProject}
and t_storage.owner_unit = #{ownerUnit}
and t_storage.wbs_element = #{wbsElement}
and t_storage.receiver = #{receiver}
and t_storage.warehouse = #{warehouse}
and t_storage.is_to_i6000 = #{isToI6000}
ORDER BY t_storage.create_time DESC

SELECT
    a.*,
    b.device_code
FROM
    idevelop_device_storage a
LEFT JOIN idevelop_device_storage_list b ON a.id = b.storage_id AND b.is_deleted = 0
WHERE a.is_deleted = 0
    
        AND b.device_code LIKE CONCAT('%', #{so.deviceCode}, '%')
    
    
        AND a.owner_unit = #{so.ownerUnitCode}
    
    
        AND a.dept_code = #{so.deptCode}
    
    
        AND a.device_source = #{so.deviceSourceCode}
    
    
        AND a.device_category = #{so.deviceCategory}
    
    
        AND a.device_type = #{so.deviceType}
    
    
        AND a.warehouse = #{so.warehouse}
    
    
        AND a.wbs_project = #{so.wbsProject}
    
    
        AND a.region_code LIKE CONCAT(#{so.regionCode}, '%')
    
    
        AND a.storage_time BETWEEN #{so.startDate} AND #{so.endDate}
    
    GROUP BY a.id
    ORDER BY a.create_time DESC
